import { useCallback, useEffect, useState } from 'react'
import { api, type Meeting, type MeetingInput, type ProjectMember } from '../lib/api'
import Button from './ui/Button'
import TextInput from './ui/TextInput'
import FormError from './ui/FormError'

interface MeetingsProps {
  projectId: number
}

interface Draft {
  title: string
  startsAt: string
  endsAt: string
  agenda: string
  minutes: string
  attendeeIds: number[]
}

// datetime-local inputs work in the viewer's local time, without a zone suffix.
export function toLocalInput(iso: string): string {
  const d = new Date(iso)
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`
}

function draftFrom(m: Meeting): Draft {
  return {
    title: m.title,
    startsAt: toLocalInput(m.starts_at),
    endsAt: toLocalInput(m.ends_at),
    agenda: m.agenda,
    minutes: m.minutes,
    attendeeIds: m.attendees.map(a => a.user_id),
  }
}

function newDraft(members: ProjectMember[]): Draft {
  const start = new Date()
  start.setMinutes(start.getMinutes() < 30 ? 0 : 30, 0, 0)
  const end = new Date(start.getTime() + 30 * 60 * 1000)
  return {
    title: '',
    startsAt: toLocalInput(start.toISOString()),
    endsAt: toLocalInput(end.toISOString()),
    agenda: '',
    minutes: '',
    attendeeIds: members.map(m => m.user_id),
  }
}

const formatWhen = (m: Meeting) => {
  const start = new Date(m.starts_at)
  const end = new Date(m.ends_at)
  const time: Intl.DateTimeFormatOptions = { hour: 'numeric', minute: '2-digit' }
  return `${start.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })} · ${start.toLocaleTimeString(undefined, time)}–${end.toLocaleTimeString(undefined, time)}`
}

const textareaClass =
  'w-full rounded-md bg-dark-bg-primary border border-dark-border-subtle px-3 py-2 text-sm text-dark-text-primary font-mono focus:outline-none focus:ring-2 focus:ring-primary-500'

export default function Meetings({ projectId }: MeetingsProps) {
  const [meetings, setMeetings] = useState<Meeting[]>([])
  const [members, setMembers] = useState<ProjectMember[]>([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [selectedId, setSelectedId] = useState<number | 'new' | null>(null)
  const [draft, setDraft] = useState<Draft | null>(null)
  const [saving, setSaving] = useState(false)
  const [saveError, setSaveError] = useState<string | null>(null)
  const [confirmDelete, setConfirmDelete] = useState(false)

  const load = useCallback(async () => {
    try {
      setLoading(true)
      setLoadError(null)
      const [ms, mem] = await Promise.all([api.getMeetings(projectId), api.getProjectMembers(projectId)])
      setMeetings(ms)
      setMembers(mem)
      if (ms.length > 0) {
        setSelectedId(ms[0].id)
        setDraft(draftFrom(ms[0]))
      }
    } catch (err) {
      setLoadError(err instanceof Error ? err.message : 'Failed to load meetings')
    } finally {
      setLoading(false)
    }
  }, [projectId])

  useEffect(() => {
    void load()
  }, [load])

  const select = (m: Meeting) => {
    setSelectedId(m.id)
    setDraft(draftFrom(m))
    setSaveError(null)
    setConfirmDelete(false)
  }

  const startNew = () => {
    setSelectedId('new')
    setDraft(newDraft(members))
    setSaveError(null)
  }

  const toggleAttendee = (userId: number) => {
    if (!draft) return
    const ids = draft.attendeeIds.includes(userId)
      ? draft.attendeeIds.filter(id => id !== userId)
      : [...draft.attendeeIds, userId]
    setDraft({ ...draft, attendeeIds: ids })
  }

  const save = async () => {
    if (!draft || selectedId === null) return
    const input: MeetingInput = {
      title: draft.title.trim(),
      starts_at: new Date(draft.startsAt).toISOString(),
      ends_at: new Date(draft.endsAt).toISOString(),
      agenda: draft.agenda,
      minutes: draft.minutes,
    }
    // Only resend attendees when they changed, so a member leaving the project doesn't block saving minutes.
    const original = meetings.find(m => m.id === selectedId)?.attendees.map(a => a.user_id) ?? []
    const changed = selectedId === 'new' || original.length !== draft.attendeeIds.length ||
      original.some(id => !draft.attendeeIds.includes(id))
    if (changed) input.attendee_ids = draft.attendeeIds
    try {
      setSaving(true)
      setSaveError(null)
      const saved = selectedId === 'new'
        ? await api.createMeeting(projectId, input)
        : await api.updateMeeting(selectedId, input)
      setMeetings(prev => {
        const rest = prev.filter(m => m.id !== saved.id)
        return [saved, ...rest].sort((a, b) => b.starts_at.localeCompare(a.starts_at))
      })
      select(saved)
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : 'Failed to save meeting')
    } finally {
      setSaving(false)
    }
  }

  const remove = async () => {
    if (typeof selectedId !== 'number') return
    try {
      setSaving(true)
      await api.deleteMeeting(selectedId)
      const rest = meetings.filter(m => m.id !== selectedId)
      setMeetings(rest)
      if (rest.length > 0) select(rest[0])
      else {
        setSelectedId(null)
        setDraft(null)
      }
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : 'Failed to delete meeting')
    } finally {
      setSaving(false)
    }
  }

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center" role="status" aria-label="Loading meetings">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-500" />
      </div>
    )
  }
  if (loadError) {
    return (
      <div className="flex-1 p-6">
        <FormError message={loadError} />
        <Button variant="secondary" size="sm" className="mt-3" onClick={() => void load()}>Retry</Button>
      </div>
    )
  }

  return (
    <div className="flex-1 flex min-h-0">
      <aside className="w-72 border-r border-dark-border-subtle flex flex-col" aria-label="Meetings">
        <div className="p-3 flex items-center justify-between border-b border-dark-border-subtle">
          <h2 className="text-sm font-semibold text-dark-text-primary">Meetings</h2>
          <Button size="sm" onClick={startNew}>New meeting</Button>
        </div>
        {meetings.length === 0 ? (
          <p className="p-4 text-xs text-dark-text-tertiary">No meetings yet. Record your first one.</p>
        ) : (
          <ul className="overflow-y-auto flex-1">
            {meetings.map(m => (
              <li key={m.id}>
                <button
                  onClick={() => select(m)}
                  aria-current={selectedId === m.id ? 'true' : undefined}
                  className={`w-full text-left px-3 py-2.5 border-b border-dark-border-subtle transition-colors ${selectedId === m.id ? 'bg-dark-bg-tertiary' : 'hover:bg-dark-bg-secondary'}`}
                >
                  <p className="text-sm font-medium text-dark-text-primary truncate">{m.title}</p>
                  <p className="text-xs text-dark-text-tertiary mt-0.5">{formatWhen(m)}</p>
                  <p className="text-xs text-dark-text-quaternary mt-0.5">{m.attendees.length} attendees</p>
                </button>
              </li>
            ))}
          </ul>
        )}
      </aside>

      <section className="flex-1 overflow-y-auto p-6">
        {!draft ? (
          <p className="text-sm text-dark-text-tertiary">Select a meeting or create a new one.</p>
        ) : (
          <form
            className="max-w-3xl space-y-5"
            onSubmit={e => {
              e.preventDefault()
              void save()
            }}
          >
            <TextInput id="meeting-title" label="Title" value={draft.title} required maxLength={200}
              onChange={e => setDraft({ ...draft, title: e.target.value })} />
            <div className="grid grid-cols-2 gap-4">
              <TextInput id="meeting-start" type="datetime-local" label="Starts" value={draft.startsAt} required
                onChange={e => setDraft({ ...draft, startsAt: e.target.value })} />
              <TextInput id="meeting-end" type="datetime-local" label="Ends" value={draft.endsAt} required
                onChange={e => setDraft({ ...draft, endsAt: e.target.value })} />
            </div>

            <fieldset>
              <legend className="block text-xs font-medium text-dark-text-tertiary mb-1.5">Attendees</legend>
              <div className="flex flex-wrap gap-2">
                {members.map(m => (
                  <label key={m.user_id} className="flex items-center gap-2 rounded-md border border-dark-border-subtle px-2.5 py-1.5 text-xs text-dark-text-secondary cursor-pointer">
                    <input type="checkbox" checked={draft.attendeeIds.includes(m.user_id)} onChange={() => toggleAttendee(m.user_id)} />
                    {m.name || m.user_name || m.email}
                  </label>
                ))}
              </div>
            </fieldset>

            <div>
              <label htmlFor="meeting-agenda" className="block text-xs font-medium text-dark-text-tertiary mb-1.5">Agenda (Markdown)</label>
              <textarea id="meeting-agenda" rows={6} className={textareaClass} value={draft.agenda}
                onChange={e => setDraft({ ...draft, agenda: e.target.value })} />
            </div>
            <div>
              <label htmlFor="meeting-minutes" className="block text-xs font-medium text-dark-text-tertiary mb-1.5">Minutes (Markdown)</label>
              <textarea id="meeting-minutes" rows={12} className={textareaClass} value={draft.minutes}
                onChange={e => setDraft({ ...draft, minutes: e.target.value })} />
            </div>

            {saveError && <FormError message={saveError} />}
            <div className="flex items-center gap-3">
              <Button type="submit" disabled={saving}>{saving ? 'Saving…' : selectedId === 'new' ? 'Create meeting' : 'Save'}</Button>
              {typeof selectedId === 'number' && (
                <Button type="button" variant="danger" disabled={saving}
                  onClick={() => (confirmDelete ? void remove() : setConfirmDelete(true))}>
                  {confirmDelete ? 'Confirm delete' : 'Delete'}
                </Button>
              )}
            </div>
          </form>
        )}
      </section>
    </div>
  )
}

package api

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"testing"

	"go.uber.org/zap/zaptest"

	"taskai/internal/config"
	"taskai/internal/db"
)

func TestMeetingHandlers(t *testing.T) {
	ts := NewTestServer(t)
	defer ts.Close()

	owner := ts.CreateTestUser(t, "owner@example.com", "password123")
	member := ts.CreateTestUser(t, "member@example.com", "password123")
	outsider := ts.CreateTestUser(t, "outsider@example.com", "password123")
	projectID := ts.CreateTestProject(t, owner, "Engineering")
	ts.AddProjectMember(t, projectID, member, owner, "member")
	runMeetingTests(t, ts, owner, member, outsider, projectID)
}

func TestPostgresMeetingHandlers(t *testing.T) {
	dsn := os.Getenv("TEST_POSTGRES_DSN")
	if dsn == "" {
		t.Skip("TEST_POSTGRES_DSN not set")
	}
	ctx := context.Background()
	database, err := db.New(db.Config{Driver: "postgres", DSN: dsn, MigrationsPath: "./../../internal/db/migrations"}, zaptest.NewLogger(t))
	if err != nil {
		t.Fatal(err)
	}
	defer database.Close()
	s := NewServer(database, &config.Config{JWTSecret: "test-secret-key", JWTExpiryHours: 24}, zaptest.NewLogger(t))
	ts := &TestServer{Server: s, DB: database}

	var ids [3]int64
	for i, email := range []string{"pg-mtg-owner@example.com", "pg-mtg-member@example.com", "pg-mtg-out@example.com"} {
		if err := database.QueryRowContext(ctx, `INSERT INTO users (email, password_hash) VALUES ($1, 'x') RETURNING id`, email).Scan(&ids[i]); err != nil {
			t.Fatal(err)
		}
	}
	var projectID int64
	if err := database.QueryRowContext(ctx, `INSERT INTO projects (owner_id, name) VALUES ($1, 'Engineering') RETURNING id`, ids[0]).Scan(&projectID); err != nil {
		t.Fatal(err)
	}
	for i, role := range []string{"owner", "member"} {
		if _, err := database.ExecContext(ctx, `INSERT INTO project_members (project_id, user_id, role, granted_by) VALUES ($1, $2, $3, $4)`, projectID, ids[i], role, ids[0]); err != nil {
			t.Fatal(err)
		}
	}
	runMeetingTests(t, ts, ids[0], ids[1], ids[2], projectID)
}

func runMeetingTests(t *testing.T, ts *TestServer, owner, member, outsider, projectID int64) {
	pid := fmt.Sprintf("%d", projectID)
	path := "/api/projects/" + pid + "/meetings"

	create := func(user int64, body map[string]interface{}) (int, Meeting) {
		rec, req := ts.MakeAuthRequest(t, http.MethodPost, path, body, user, map[string]string{"id": pid})
		ts.HandleCreateMeeting(rec, req)
		var m Meeting
		if rec.Code == http.StatusCreated {
			DecodeJSON(t, rec, &m)
		}
		return rec.Code, m
	}
	valid := func(extra map[string]interface{}) map[string]interface{} {
		b := map[string]interface{}{"title": "Superteam sync", "starts_at": "2026-11-20T13:30:00-05:00", "ends_at": "2026-11-20T14:00:00-05:00"}
		for k, v := range extra {
			b[k] = v
		}
		return b
	}

	tests := []struct {
		name          string
		user          int64
		body          map[string]interface{}
		wantStatus    int
		wantAttendees int
	}{
		{"defaults to every project member", owner, valid(nil), http.StatusCreated, 2},
		{"explicit attendees", member, valid(map[string]interface{}{"attendee_ids": []int64{member}}), http.StatusCreated, 1},
		{"outsider forbidden", outsider, valid(nil), http.StatusForbidden, 0},
		{"non-member attendee rejected", owner, valid(map[string]interface{}{"attendee_ids": []int64{outsider}}), http.StatusBadRequest, 0},
		{"missing title", owner, valid(map[string]interface{}{"title": "  "}), http.StatusBadRequest, 0},
		{"ends before start", owner, valid(map[string]interface{}{"ends_at": "2026-11-20T13:00:00-05:00"}), http.StatusBadRequest, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			status, m := create(tt.user, tt.body)
			AssertStatusCode(t, status, tt.wantStatus)
			if status == http.StatusCreated && len(m.Attendees) != tt.wantAttendees {
				t.Errorf("attendees = %d, want %d", len(m.Attendees), tt.wantAttendees)
			}
		})
	}

	_, m := create(owner, valid(map[string]interface{}{"agenda": "1. Intros"}))
	mid := fmt.Sprintf("%d", m.ID)
	if m.StartsAt.UTC().Hour() != 18 || m.StartsAt.Minute() != 30 {
		t.Errorf("starts_at = %v, want 18:30 UTC", m.StartsAt)
	}

	t.Run("update minutes and attendees", func(t *testing.T) {
		body := map[string]interface{}{"minutes": "Decided X", "attendee_ids": []int64{owner}}
		rec, req := ts.MakeAuthRequest(t, http.MethodPatch, "/api/meetings/"+mid, body, member, map[string]string{"id": mid})
		ts.HandleUpdateMeeting(rec, req)
		AssertStatusCode(t, rec.Code, http.StatusOK)
		var got Meeting
		DecodeJSON(t, rec, &got)
		if got.Minutes != "Decided X" || got.Agenda != "1. Intros" || len(got.Attendees) != 1 {
			t.Errorf("unexpected meeting after update: %+v", got)
		}
	})

	t.Run("list newest first, outsider cannot get", func(t *testing.T) {
		rec, req := ts.MakeAuthRequest(t, http.MethodGet, path, nil, member, map[string]string{"id": pid})
		ts.HandleListMeetings(rec, req)
		AssertStatusCode(t, rec.Code, http.StatusOK)
		var list []Meeting
		DecodeJSON(t, rec, &list)
		if len(list) != 3 {
			t.Fatalf("list = %d meetings, want 3", len(list))
		}
		rec, req = ts.MakeAuthRequest(t, http.MethodGet, "/api/meetings/"+mid, nil, outsider, map[string]string{"id": mid})
		ts.HandleGetMeeting(rec, req)
		AssertStatusCode(t, rec.Code, http.StatusForbidden)
	})

	t.Run("delete", func(t *testing.T) {
		rec, req := ts.MakeAuthRequest(t, http.MethodDelete, "/api/meetings/"+mid, nil, owner, map[string]string{"id": mid})
		ts.HandleDeleteMeeting(rec, req)
		AssertStatusCode(t, rec.Code, http.StatusNoContent)
		rec, req = ts.MakeAuthRequest(t, http.MethodGet, "/api/meetings/"+mid, nil, owner, map[string]string{"id": mid})
		ts.HandleGetMeeting(rec, req)
		AssertStatusCode(t, rec.Code, http.StatusNotFound)
	})
}

